import pytest

import bedrock_protocol as bp
from bedrock_protocol import DecodeError, EncodeError, _core, v671, v729, v766, v924, v1001, v2225

# generated by gophertunnel 500a41a:
# protocol.NewWriter(buf, 0).UBlockPos(&protocol.BlockPos{0, -1, 0})
NETWORK_BLOCK_POSITION = bytes.fromhex("00ffffffff0f00")

SLOT_PREFIX = bytes.fromhex("030340120000")

# generated by gophertunnel 6353c49:
# protocol.StackResponseSlotInfo{Slot: 3, HotbarSlot: 3, Count: 64, StackNetworkID: 9, DurabilityCorrection: -32768}
SLOT_MINIMUM = bytes.fromhex("030340120000ffff03")

# generated by gophertunnel 6353c49:
# protocol.StackResponseSlotInfo{Slot: 3, HotbarSlot: 3, Count: 64, StackNetworkID: 9, DurabilityCorrection: 32767}
SLOT_MAXIMUM = bytes.fromhex("030340120000feff03")


@pytest.mark.parametrize(
    ("body", "packet"),
    [
        pytest.param(
            bytes(3) + bytes.fromhex("ffffffff10") + bytes(4), bp.NetworkChunkPublisherUpdatePacket, id="uvarint32"
        ),
        pytest.param(bytes.fromhex("ffffffffffffffffff02") + bytes(13), bp.SetActorMotionPacket, id="uvarint64"),
    ],
)
def test_decode_rejects_a_varint_that_overflows_its_type(body, packet):
    with pytest.raises(ValueError, match="at byte"):
        v2225.decode(packet, body)


def test_decode_rejects_a_string_length_beyond_the_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.decode(bp.ServerToClientHandshakePacket, bytes.fromhex("ffffffff0f"))


@pytest.mark.parametrize(
    ("packet", "body", "message"),
    [
        pytest.param(
            bp.UpdateAttributesPacket,
            bytes.fromhex("00ffffffff0f"),
            r"^UpdateAttributesPacket\.attribute_data\[0\]\.min_value: truncated at byte 6 of 6$",
            id="list",
        ),
        pytest.param(
            bp.BlockActorDataPacket,
            bytes(3) + bytes.fromhex("0a00090161") + bytes.fromhex("09feffffff0f") * 7 + bytes.fromhex("01feffffff0f"),
            r"^BlockActorDataPacket\.data: truncated at byte 56 of 56$",
            id="nested nbt list",
        ),
    ],
)
def test_decode_rejects_a_list_count_beyond_the_body(packet, body, message):
    with pytest.raises(DecodeError, match=message):
        v2225.decode(packet, body)


@pytest.mark.parametrize(
    ("packet", "body"),
    [
        pytest.param(bp.BlockActorDataPacket, bytes(3) + bytes.fromhex("0a00") * 513 + bytes(513), id="nbt compound"),
        pytest.param(
            bp.BlockActorDataPacket,
            bytes(3) + bytes.fromhex("0a000900") + bytes.fromhex("0902") * 511 + bytes.fromhex("090000"),
            id="nbt list",
        ),
        pytest.param(
            bp.LevelEventGenericPacket, bytes(1) + bytes.fromhex("0a00") * 512 + bytes(513), id="nbt compound tag data"
        ),
        pytest.param(
            v924.ClientboundDataStorePacket,
            bytes.fromhex("0101000000000000") + bytes.fromhex("0500000001") * 512 + bytes(4),
            id="dynamic value array",
        ),
        pytest.param(
            v924.ClientboundDataStorePacket,
            bytes.fromhex("0101000000000000") + bytes.fromhex("060000000100") * 512 + bytes(4),
            id="dynamic value object",
        ),
    ],
)
def test_decode_accepts_a_tree_nested_512_levels_deep(packet, body):
    assert v2225.encode(v2225.decode(packet, body)) == body


@pytest.mark.parametrize(
    ("packet", "body", "message"),
    [
        pytest.param(
            bp.BlockActorDataPacket,
            bytes(3) + bytes.fromhex("0a00") * 514 + bytes(514),
            r"^BlockActorDataPacket\.data: out of range at byte 1031 of 1545$",
            id="nbt compound",
        ),
        pytest.param(
            bp.BlockActorDataPacket,
            bytes(3) + bytes.fromhex("0a000900") + bytes.fromhex("0902") * 512 + bytes.fromhex("090000"),
            r"^BlockActorDataPacket\.data: out of range at byte 1031 of 1034$",
            id="nbt list",
        ),
        pytest.param(
            bp.LevelEventGenericPacket,
            bytes(1) + bytes.fromhex("0a00") * 513 + bytes(514),
            r"^LevelEventGenericPacket\.data: out of range at byte 1027 of 1541$",
            id="nbt compound tag data",
        ),
        pytest.param(
            bp.BlockActorDataPacket,
            bytes(3) + bytes.fromhex("0a00") * 20000,
            r"^BlockActorDataPacket\.data: out of range at byte 1031 of 40003$",
            id="unclosed nbt compound",
        ),
        pytest.param(
            v924.ClientboundDataStorePacket,
            bytes.fromhex("0101000000000000") + bytes.fromhex("0500000001") * 513 + bytes(4),
            r"^ClientboundDataStorePacket\.updates\[0\]\.new_data: out of range at byte 2573 of 2577$",
            id="dynamic value array",
        ),
        pytest.param(
            v924.ClientboundDataStorePacket,
            bytes.fromhex("0101000000000000") + bytes.fromhex("060000000100") * 513 + bytes(4),
            r"^ClientboundDataStorePacket\.updates\[0\]\.new_data: out of range at byte 3086 of 3090$",
            id="dynamic value object",
        ),
        pytest.param(
            v924.ClientboundDataStorePacket,
            bytes.fromhex("0101000000000000") + bytes.fromhex("0500000001") * 40000,
            r"^ClientboundDataStorePacket\.updates\[0\]\.new_data: out of range at byte 2573 of 200008$",
            id="unclosed dynamic value",
        ),
    ],
)
def test_decode_rejects_a_tree_nested_deeper_than_512_levels(packet, body, message):
    with pytest.raises(DecodeError, match=message):
        v2225.decode(packet, body)


def test_decode_rejects_a_negative_nbt_byte_array_length():
    with pytest.raises(ValueError, match="at byte"):
        v2225.decode(bp.BlockActorDataPacket, bytes(3) + bytes.fromhex("0a000701610100"))


SLOTS = [
    pytest.param(-32768, SLOT_MINIMUM, id="minimum"),
    pytest.param(32767, SLOT_MAXIMUM, id="maximum"),
]


@pytest.mark.parametrize(("durability_correction", "golden"), SLOTS)
def test_an_int16_varint_encodes_at_its_bounds(durability_correction, golden):
    slot = v766.ItemStackResponseSlotInfo(
        requested_slot=3,
        slot=3,
        amount=64,
        item_stack_net_id=bp.ItemStackNetId(raw_id=9),
        durability_correction=durability_correction,
    )
    assert _core.encode(v1001.VERSION, slot) == golden


@pytest.mark.parametrize(("durability_correction", "golden"), SLOTS)
def test_an_int16_varint_decodes_at_its_bounds(durability_correction, golden):
    slot = v766.ItemStackResponseSlotInfo(
        requested_slot=3,
        slot=3,
        amount=64,
        item_stack_net_id=bp.ItemStackNetId(raw_id=9),
        durability_correction=durability_correction,
    )
    assert _core.decode(v1001.VERSION, v766.ItemStackResponseSlotInfo, golden) == slot


@pytest.mark.parametrize("encoded", ["808004", "818004"])
def test_decode_rejects_an_int16_varint_beyond_its_bounds(encoded):
    with pytest.raises(ValueError, match="at byte"):
        _core.decode(v1001.VERSION, v766.ItemStackResponseSlotInfo, SLOT_PREFIX + bytes.fromhex(encoded))


def test_an_int32_encodes_at_the_bound_of_its_one_byte_encoding():
    assert _core.encode(v2225.VERSION, bp.ItemEnchantOption(cost=255)) == bytes.fromhex("ff000000000000000000")


@pytest.mark.parametrize("cost", [pytest.param(300, id="above"), pytest.param(-1, id="negative")])
def test_encode_rejects_an_int32_beyond_its_one_byte_encoding(cost):
    with pytest.raises(EncodeError, match=r"^ItemEnchantOption\.cost: out of range$"):
        _core.encode(v2225.VERSION, bp.ItemEnchantOption(cost=cost))


def test_a_signed_member_of_an_unsigned_varint_encodes_to_its_golden():
    assert _core.encode(v729.VERSION, v671.NetworkBlockPosition(x=0, y=-1, z=0)) == NETWORK_BLOCK_POSITION


def test_a_signed_member_of_an_unsigned_varint_decodes_from_its_golden():
    decoded = _core.decode(v729.VERSION, v671.NetworkBlockPosition, NETWORK_BLOCK_POSITION)
    assert decoded == v671.NetworkBlockPosition(x=0, y=-1, z=0)
